//! `os.lazy.usb.audio.v1` (`idl/usb_audio.midl`, docs/usb-audio-plan.md):
//! the USB audio function `usbd` drives, as `sndd usb=1` talks to it.
//!
//! The stubs are generated by `midlc`; this module adds the service name,
//! the request framing and the blocking [`Client`] `sndd`'s USB card uses.
//! Failures come back as the shared structured error field.

use alloc::vec::Vec;

use libmessenger::{Buffer, Header, Object, Parcel, VERSION};

use super::services::error_field;
use super::{registry, Endpoint, Error, Result};

/// The generated stubs.
pub use messenger_generated::os_lazy_usb_audio_v1 as wire;

pub use wire::{Device, Progress};

/// The name `usbd` registers while an audio device is bound.
pub const NAME: &str = "os.lazy.usb.audio";

/// The interface id every parcel carries.
pub const INTERFACE: u64 = wire::INTERFACE_ID;

/// A parcel of `method` carrying an encoded `body` and its `objects`
/// (only `Attach` carries one).
pub fn parcel(method: u32, body: Vec<u8>, objects: Vec<Object>) -> Parcel {
    Parcel {
        header: Header {
            version: VERSION,
            flags: 0,
            interface_id: INTERFACE,
            method,
            txn_id: 0,
            reply_to: 0,
            deadline_ns: 0,
        },
        body,
        objects,
    }
}

/// A blocking client of `usbd`'s audio function.
pub struct Client {
    endpoint: Endpoint,
}

impl Client {
    /// Resolve [`NAME`]: `ENOENT` (or another error) while no device is bound.
    pub fn connect() -> Result<Client> {
        Ok(Client {
            endpoint: registry::resolve(NAME)?,
        })
    }

    fn call(&self, method: u32, body: Vec<u8>, objects: Vec<Object>) -> Result<Vec<u8>> {
        let reply = self.endpoint.call(&parcel(method, body, objects), None)?;
        match error_field(&reply)? {
            Some(code) => Err(Error::Errno(-code)),
            None => Ok(reply.body),
        }
    }

    pub fn describe(&self) -> Result<Device> {
        let body = self.call(wire::METHOD_DESCRIBE, Vec::new(), Vec::new())?;
        Ok(wire::decode_describe_reply(&body)
            .map_err(Error::Parcel)?
            .device)
    }

    /// Share `len` bytes of the buffer `handle` as the staging area.
    pub fn attach(&self, handle: u64, len: u64) -> Result<()> {
        let (body, objects) = wire::encode_attach_args(&wire::AttachArgs {
            staging: Buffer::whole(handle, len),
        })
        .map_err(Error::Parcel)?;
        self.call(wire::METHOD_ATTACH, body, objects).map(|_| ())
    }

    /// Switch the device to `rate` Hz (or the closest it has); the rate granted.
    pub fn configure(&self, rate: u32) -> Result<u32> {
        let body =
            wire::encode_configure_args(&wire::ConfigureArgs { rate }).map_err(Error::Parcel)?;
        let reply = self.call(wire::METHOD_CONFIGURE, body, Vec::new())?;
        Ok(wire::decode_configure_reply(&reply)
            .map_err(Error::Parcel)?
            .granted)
    }

    pub fn start(&self) -> Result<()> {
        self.call(wire::METHOD_START, Vec::new(), Vec::new())
            .map(|_| ())
    }

    pub fn stop(&self) -> Result<()> {
        self.call(wire::METHOD_STOP, Vec::new(), Vec::new())
            .map(|_| ())
    }

    pub fn release(&self) -> Result<()> {
        self.call(wire::METHOD_RELEASE, Vec::new(), Vec::new())
            .map(|_| ())
    }

    /// Queue `len` bytes at `offset` of the staging buffer.
    pub fn submit(&self, slot: u32, offset: u32, len: u32) -> Result<()> {
        let body = wire::encode_submit_args(&wire::SubmitArgs { slot, offset, len })
            .map_err(Error::Parcel)?;
        self.call(wire::METHOD_SUBMIT, body, Vec::new()).map(|_| ())
    }

    pub fn reap(&self) -> Result<Progress> {
        let body = self.call(wire::METHOD_REAP, Vec::new(), Vec::new())?;
        Ok(wire::decode_reap_reply(&body)
            .map_err(Error::Parcel)?
            .progress)
    }

    /// Give up the handle: it was obtained by name, so it is released, not
    /// closed (closing would end `usbd`'s service side).
    pub fn release_handle(self) {
        let _ = self.endpoint.release();
    }
}
